 body=<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Panel — Permisos Ambientales</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Serif:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500;600&display=swap" rel="stylesheet">
<link rel="stylesheet" href="css/estilos.css">
</head>
<body>
<div class="shell">
  <aside class="rail">
    <div class="rail-brand">
      <div class="seal">
        <svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.1">
          <circle cx="20" cy="20" r="17"/>
          <path d="M6 24c4-4 8 4 12 0s8-6 12 0" opacity="0.6"/>
          <path d="M7 16c4-3 8 3 12 0s8-5 12 0" opacity="0.45"/>
          <circle cx="20" cy="20" r="2.2" fill="currentColor" stroke="none"/>
        </svg>
      </div>
      <div><b>Permisos<br>Ambientales</b><span>Caso 8 · MiAmbiente</span></div>
    </div>
    <nav>
      <a href="dashboard.html" class="active">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3.5" y="3.5" width="7" height="7"/><rect x="13.5" y="3.5" width="7" height="7"/><rect x="3.5" y="13.5" width="7" height="7"/><rect x="13.5" y="13.5" width="7" height="7"/></svg>
        Panel
      </a>
      <a href="expedientes.html">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 6.5a1.5 1.5 0 0 1 1.5-1.5H10l2 2.5h6.5A1.5 1.5 0 0 1 20 9v9a1.5 1.5 0 0 1-1.5 1.5h-13A1.5 1.5 0 0 1 4 18z"/></svg>
        Mis expedientes
      </a>
      <a href="expediente-nuevo.html">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M6 3.5h9l4 4V20a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4.5a1 1 0 0 1 1-1z"/><path d="M12 11v6M9 14h6"/></svg>
        Nuevo expediente
      </a>
      <a href="historial.html" id="nav-historial">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/></svg>
        Historial
      </a>
      <a href="equipo.html" id="nav-equipo" style="display:none;">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="9" cy="8.5" r="3.2"/><path d="M3.5 19c.6-3.2 2.8-5 5.5-5s4.9 1.8 5.5 5"/><circle cx="17" cy="9.5" r="2.4"/><path d="M15.8 14.2c2.3.2 4 1.8 4.6 4.8"/></svg>
        Equipo
      </a>
      <a href="consulta-publica.html">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="10.5" cy="10.5" r="6.5"/><path d="M19.5 19.5 15 15"/></svg>
        Consulta pública
      </a>
    </nav>
    <div class="rail-foot">SEMESTRE II · 2026<br>Sprint 9</div>
  </aside>

  <div class="main">
    <div class="topbar">
      <span class="crumb">PANEL</span>
      <div class="who"></div>
    </div>

    <div class="content">
      <div class="content-head">
        <h2>Panel principal</h2>
      </div>

      <div class="stat-row">
        <div class="stat"><div class="num">—</div><div class="lbl">Expedientes activos</div></div>
        <div class="stat"><div class="num">—</div><div class="lbl">Pendientes de subsanación</div></div>
        <div class="stat"><div class="num">—</div><div class="lbl">Alertas próximas</div></div>
        <div class="stat"><div class="num">—</div><div class="lbl">Aprobados por MiAmbiente</div></div>
      </div>

      <div class="panel" id="panel-prioridades" style="display:none;">
        <h3>Dónde poner al equipo hoy</h3>
        <p class="panel-note">Los expedientes menos preparados, según el Índice de Preparación (IPE): 50% documentos, 30% plazo y 20% vigencia. Listo desde 80; en riesgo por debajo de 50.</p>
        <ul class="reg-list" id="lista-prioridades"></ul>
      </div>

      <div class="panel">
        <h3>Actividad reciente</h3>
        <p class="panel-note">Últimos movimientos sobre tus expedientes.</p>
        <ul class="reg-list" id="lista-recientes"></ul>
      </div>

      <div class="panel">
        <h3>Alertas próximas</h3>
        <p class="panel-note">Documentos con vigencia por vencer.</p>
        <ul class="reg-list" id="lista-alertas"></ul>
      </div>
    </div>
  </div>
</div>

<script src="js/api.js"></script>
<script>
const usuario = requireAuth();
if (usuario) {
  pintarTopbar();

  apiFetch('/dashboard').then(d => {
    const nums = document.querySelectorAll('.stat .num');
    if (d.metricas && nums.length >= 4) {
      nums[0].textContent = d.metricas.activos;
      nums[1].textContent = d.metricas.pendientes;
      nums[2].textContent = d.metricas.alertas;
      nums[3].textContent = d.metricas.aprobados;
    }

    // HU-15: solo la consultora ve las prioridades (el promotor no recibe el dato).
    if (Array.isArray(d.prioridades) && (esJefe() || esConsultor())) {
      document.getElementById('panel-prioridades').style.display = 'block';
      const ulP = document.getElementById('lista-prioridades');
      ulP.innerHTML = d.prioridades.length ? '' : '<li style="color:var(--ink-faint);">No hay expedientes abiertos.</li>';
      d.prioridades.forEach(p => {
        ulP.innerHTML += `<li>
          <span><span class="code">${esc(p.codigo)}</span>${esc(p.proyecto)}
            <br><span style="font-size:13px; color:var(--ink-soft);">${esc(p.proxima_accion || 'Sin acciones pendientes')}</span></span>
          <span style="text-align:right; white-space:nowrap;">${etiquetaIpe({ valor: p.ipe, banda: p.banda, banda_texto: p.banda_texto })}
            <br><a href="expediente-detalle.html?codigo=${encodeURIComponent(p.codigo)}">Ver</a></span>
        </li>`;
      });
    }

    const ulR = document.getElementById('lista-recientes');
    ulR.innerHTML = '';
    if (d.recientes && d.recientes.length) {
      d.recientes.forEach(r => {
        ulR.innerHTML += `<li><span><span class="code">${esc(r.codigo)}</span>${esc(r.proyecto)}</span> <span class="${claseEstado(r.estado)}">${textoEstado(r.estado)}</span></li>`;
      });
    } else {
      ulR.innerHTML = '<li style="color:var(--ink-faint);">Sin expedientes registrados.</li>';
    }

       const ulA = document.getElementById('lista-alertas');
    ulA.innerHTML = '';
    if (d.alertas && d.alertas.length) {
      d.alertas.forEach(a => {
        ulA.innerHTML += `<li>
          <span><span class="code">${esc(a.codigo)}</span> ${esc(a.descripcion)}</span> 
          <a href="expediente-detalle.html?codigo=${encodeURIComponent(a.codigo)}">Ver</a>
        </li>`;
      });
    } else {
      ulA.innerHTML = '<li style="color:var(--ink-faint);">Sin alertas próximas en este momento.</li>';
    }
  }).catch(console.error);
}
</script>
</body>
</html>

