 body=<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Mis expedientes — Permisos Ambientales</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Serif:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500;600&display=swap" rel="stylesheet">
<link rel="stylesheet" href="css/estilos.css">
<style>
  /* Sprint 8: la vista del jefe tiene 9 columnas; menos relleno para que quepan. */
  .ledger.compacta th, .ledger.compacta td { padding-right: 10px; }
  .ledger.compacta .status { font-size: 12px; padding: 3px 8px 3px 6px; }
</style>
</head>
<body>
<div class="shell">
  <aside class="rail">
    <div class="rail-brand">
      <div class="seal">
        <svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.1">
          <circle cx="20" cy="20" r="17"/>
          <path d="M6 24c4-4 8 4 12 0s8-6 12 0" opacity="0.6"/>
          <path d="M7 16c4-3 8 3 12 0s8-5 12 0" opacity="0.45"/>
          <circle cx="20" cy="20" r="2.2" fill="currentColor" stroke="none"/>
        </svg>
      </div>
      <div><b>Permisos<br>Ambientales</b><span>Caso 8 · MiAmbiente</span></div>
    </div>
    <nav>
      <a href="dashboard.html">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3.5" y="3.5" width="7" height="7"/><rect x="13.5" y="3.5" width="7" height="7"/><rect x="3.5" y="13.5" width="7" height="7"/><rect x="13.5" y="13.5" width="7" height="7"/></svg>
        Panel
      </a>
      <a href="expedientes.html" class="active">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 6.5a1.5 1.5 0 0 1 1.5-1.5H10l2 2.5h6.5A1.5 1.5 0 0 1 20 9v9a1.5 1.5 0 0 1-1.5 1.5h-13A1.5 1.5 0 0 1 4 18z"/></svg>
        Mis expedientes
      </a>
      <a href="expediente-nuevo.html">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M6 3.5h9l4 4V20a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4.5a1 1 0 0 1 1-1z"/><path d="M12 11v6M9 14h6"/></svg>
        Nuevo expediente
      </a>
      <a href="historial.html" id="nav-historial">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/></svg>
        Historial
      </a>
      <a href="equipo.html" id="nav-equipo" style="display:none;">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="9" cy="8.5" r="3.2"/><path d="M3.5 19c.6-3.2 2.8-5 5.5-5s4.9 1.8 5.5 5"/><circle cx="17" cy="9.5" r="2.4"/><path d="M15.8 14.2c2.3.2 4 1.8 4.6 4.8"/></svg>
        Equipo
      </a>
      <a href="consulta-publica.html">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="10.5" cy="10.5" r="6.5"/><path d="M19.5 19.5 15 15"/></svg>
        Consulta pública
      </a>
    </nav>
    <div class="rail-foot">SEMESTRE II · 2026<br>Sprint 9</div>
  </aside>

  <div class="main">
    <div class="topbar">
      <span class="crumb">MIS EXPEDIENTES</span>
      <div class="who"></div>
    </div>

    <div class="content">
      <div class="content-head">
        <h2 id="titulo-lista">Mis expedientes</h2>
        <a href="expediente-nuevo.html" class="btn btn-brass" id="btnNuevo">+ Nuevo expediente</a>
      </div>
      <div class="panel" style="padding: 15px; margin-bottom: 20px; display: flex; gap: 10px; flex-wrap: wrap;">
        <input type="text" id="buscador" placeholder="Buscar por código o proyecto..." style="flex: 1; padding: 10px; border: 1px solid var(--line); border-radius: 4px; font-family: inherit;">

        <select id="filtro-estado" style="padding: 10px; border: 1px solid var(--line); border-radius: 4px; font-family: inherit;">
          <option value="">Todos los estados</option>
          <option value="pendiente">Pendiente de subsanación</option>
          <option value="aprobado_interno" id="opt-aprobado-interno">Aprobado internamente</option>
          <option value="evaluacion">En evaluación</option>
          <option value="aprobado">Aprobado</option>
          <option value="rechazado">Rechazado</option>
        </select>

        <select id="orden" aria-label="Ordenar" style="padding: 10px; border: 1px solid var(--line); border-radius: 4px; font-family: inherit; display:none;">
          <option value="">Más recientes primero</option>
          <option value="ipe">IPE: los menos preparados primero</option>
        </select>
      </div>
      <p class="content-lede" id="lede-lista">Expedientes que gestionas actualmente, con su categoría de impacto y estado de trámite.</p>

      <div class="panel" style="padding:0; overflow-x:auto;">
        <table class="ledger compacta tarjetas" style="margin:0; width:100%; table-layout:auto;">
          <thead>
            <tr>
              <th style="padding-left:24px; white-space:nowrap;">Código</th>
              <th>Proyecto</th>
              <th>Promotor</th>
              <th>Categoría</th>
              <th class="col-consultor" style="display:none;">Consultor</th>
              <th style="white-space:nowrap;">Estado</th>
              <th style="white-space:nowrap;">Plazo</th>
              <th class="col-ipe" style="white-space:nowrap; display:none;" title="Índice de Preparación del Expediente (0 a 100)">IPE</th>
              <th style="white-space:nowrap;">Fecha</th>
              <th style="white-space:nowrap;"></th>
            </tr>
          </thead>
          <tbody id="tabla-expedientes"></tbody>
        </table>
      </div>
    </div>
  </div>
</div>

<script src="js/api.js"></script>
<script>
let todosLosExpedientes = [];
const jefe = esJefe();
const interno = esJefe() || esConsultor();  // HU-15: el IPE es para la consultora

function renderTabla(expedientes) {
  const tbody = document.getElementById('tabla-expedientes');
  tbody.innerHTML = '';

  if (expedientes.length === 0) {
    tbody.innerHTML = '<tr><td colspan="10" class="sin-etiqueta" data-label="" style="padding:24px; color:var(--ink-faint); text-align:center;">No se encontraron expedientes con esos filtros.</td></tr>';
    return;
  }

  expedientes.forEach(e => {
    tbody.innerHTML += `
      <tr>
        <td data-label="Código" style="padding-left:24px; white-space:nowrap;"><span class="case-tag">${esc(e.codigo)}</span></td>
        <td data-label="Proyecto">${esc(e.proyecto)}</td>
        <td data-label="Promotor">${esc(e.promotor)}</td>
        <td data-label="Categoría">${fichaTier(e.categoria)}</td>
        ${jefe ? `<td data-label="Consultor">${esc(e.consultor || '—')}</td>` : ''}
        <td data-label="Estado" style="white-space:nowrap;"><span class="${claseEstado(e.estado)}">${textoEstado(e.estado)}</span></td>
        <td data-label="Plazo" style="white-space:nowrap;">${etiquetaPlazo(e.plazo)}</td>
        ${interno ? `<td data-label="IPE" style="white-space:nowrap;">${etiquetaIpe(e.ipe)}</td>` : ''}
        <td data-label="Fecha" style="white-space:nowrap; font-family:var(--mono); font-size:12.5px;">${esc(e.fecha_ingreso)}</td>
        <td data-label="" style="white-space:nowrap;"><a href="expediente-detalle.html?codigo=${encodeURIComponent(e.codigo)}">Ver →</a></td>
      </tr>
    `;
  });
}

function aplicarFiltros() {
  const texto = document.getElementById('buscador').value.toLowerCase();
  const estado = document.getElementById('filtro-estado').value;

  const filtrados = todosLosExpedientes.filter(e => {
    const coincideTexto = e.codigo.toLowerCase().includes(texto) || e.proyecto.toLowerCase().includes(texto);
    // HU-07: el promotor ve "aprobado_interno" como "Pendiente de subsanación".
    const coincideEstado = estado === '' || e.estado === estado
      || (!interno && estado === 'pendiente' && e.estado === 'aprobado_interno');
    return coincideTexto && coincideEstado;
  });

  renderTabla(filtrados);
}

const usuario = requireAuth();
if (usuario) {
  pintarTopbar();

  if (esPromotor()) {
    const btn = document.getElementById('btnNuevo');
    if (btn) btn.style.display = 'none';
    document.getElementById('opt-aprobado-interno').remove();
  }

  // HU-13: el jefe ve todos los expedientes de la consultora y de quién es cada uno.
  if (jefe) {
    document.getElementById('titulo-lista').textContent = 'Expedientes de la consultora';
    document.getElementById('lede-lista').textContent =
      'Todos los expedientes de la consultora, con su consultor, estado y plazo legal.';
    document.querySelectorAll('.col-consultor').forEach(th => th.style.display = '');
  }

  if (interno) {
    document.querySelectorAll('.col-ipe').forEach(th => th.style.display = '');
    document.getElementById('orden').style.display = '';
  }

  function cargarLista() {
    const orden = document.getElementById('orden').value;
    return apiFetch('/expedientes' + (orden ? '?orden=' + encodeURIComponent(orden) : '')).then(d => {
      todosLosExpedientes = d.expedientes || [];
      aplicarFiltros();
    }).catch(console.error);
  }

  document.getElementById('buscador').addEventListener('input', aplicarFiltros);
  document.getElementById('filtro-estado').addEventListener('change', aplicarFiltros);
  document.getElementById('orden').addEventListener('change', cargarLista);

  cargarLista();
}</script>
</body>
</html>

