            <input type="checkbox" id="acceso_publico" checked style="margin-top:3px;">
            <span><b style="font-weight:600;">Permitir la consulta pública de este proyecto.</b>
              El público verá solo el proyecto, el promotor, la categoría, el estado y el consultor responsable; nunca los documentos. El jefe de la consultora puede cambiarlo después.</span>
          </label>
        </div>
        <div class="doc-field" style="max-width:340px; margin-top:16px;">
          <label>Categoría de impacto ambiental</label>
          <select id="selectCategoria">
            <option>Categoría I — Bajo impacto</option>
            <option selected>Categoría II — Impacto moderado</option>
            <option>Categoría III — Alto impacto</option>
          </select>
        </div>
      </div>

      <div class="panel">
        <h3>Documentos requeridos por categoría</h3>
        <p class="panel-note">Estas son las carpetas que exige la categoría seleccionada. Solo se aceptan archivos PDF y ZIP (no documentos editables). Los archivos se suben después de crear el expediente.</p>
        <div class="folder-grid" id="folder-grid"></div>
      </div>

      <div class="panel">
        <h3>Verificación de requisitos</h3>
        <p class="panel-note" id="cat-note"><span class="tier"><b>II</b> Categoría II — impacto moderado</span></p>
        <ul class="checklist" id="checklist"></ul>
        <div class="checklist-warn" id="warn">El expediente se creará con todos los documentos en estado "pendiente". Deberás subir los archivos desde la vista de detalle.</div>
      </div>

      <div class="btn-row">
        <a href="expedientes.html" class="btn btn-ghost" style="border:1.5px solid var(--line);">Cancelar</a>
        <button class="btn btn-brass" id="btnGuardar">Guardar expediente</button>
      </div>
    </div>
  </div>
</div>

<script src="js/api.js"></script>
<script>
const usuario = requireAuth();
if (!usuario) throw new Error('Sin sesión');
if (usuario.rol === 'promotor') { window.location.href = 'expedientes.html'; }
pintarTopbar();

const CARPETAS_POR_CAT = {
  "I": [
    { nombre: "Línea Base",            hint: "PDF" },
    { nombre: "Plan de Manejo",        hint: "PDF" },
    { nombre: "Anexos Legales",        hint: "PDF" }
  ],
  "II": [
    { nombre: "Línea Base",            hint: "PDF" },
    { nombre: "Plan de Manejo",        hint: "PDF" },
    { nombre: "Anexos Legales",        hint: "PDF" },
    { nombre: "Cartografía",           hint: "ZIP · shapefile" }
  ],
  "III": [
    { nombre: "Línea Base",            hint: "PDF" },
    { nombre: "Plan de Manejo",        hint: "PDF" },
    { nombre: "Anexos Legales",        hint: "PDF" },
    { nombre: "Cartografía",           hint: "ZIP · shapefile" },
    { nombre: "Evidencia Foro Público", hint: "PDF · ZIP" }
  ]
};

const DESCRIPCION_CAT = {
  "I":   "bajo impacto",
  "II":  "impacto moderado",
  "III": "alto impacto"
};

let categoriaActual = "II";

function categoriaDesdeSelect(valor) {
  if (valor.includes("III")) return "III";
  if (valor.includes("I —")) return "I";
  return "II";
}

function renderCarpetas(cat) {
  const grid = document.getElementById('folder-grid');
  grid.innerHTML = '';
  CARPETAS_POR_CAT[cat].forEach(c => {
    grid.innerHTML += `
      <div class="folder">
        <div class="name">${c.nombre}</div>
        <div class="hint">${c.hint}</div>
      </div>
    `;
  });
}

function renderChecklist(cat) {
  const ul = document.getElementById('checklist');
  ul.innerHTML = '';
  CARPETAS_POR_CAT[cat].forEach(c => {
    ul.innerHTML += `
      <li>
        <span class="name">${c.nombre}</span>
        <span class="tag-missing">Pendiente</span>
      </li>
    `;
  });
}

const sel = document.getElementById('selectCategoria');
sel.addEventListener('change', () => {
  categoriaActual = categoriaDesdeSelect(sel.value);
  document.getElementById('cat-note').innerHTML =
    `<span class="tier"><b>${categoriaActual}</b> Categoría ${categoriaActual} — ${DESCRIPCION_CAT[categoriaActual]}</span>`;
  renderCarpetas(categoriaActual);
  renderChecklist(categoriaActual);
});

renderCarpetas(categoriaActual);
renderChecklist(categoriaActual);

document.getElementById('btnGuardar').addEventListener('click', async () => {
  const proyecto = document.getElementById('proyecto').value.trim();
  const promotor = document.getElementById('promotor').value.trim();
  const promotor_email = (document.getElementById('promotor_email').value || '').trim();

  if (!proyecto || !promotor) {
    mostrarToast('Completa el nombre del proyecto y el promotor.', 'error');
    return;
  }

  const btn = document.getElementById('btnGuardar');
  btn.disabled = true;
  btn.textContent = 'Guardando...';

  try {
    const r = await apiFetch('/expedientes', {
      method: 'POST',
      body: JSON.stringify({
        proyecto,
        promotor,
        promotor_email,
        categoria: categoriaActual,
        acceso_publico: document.getElementById('acceso_publico').checked
      })
    });

    if (r.ok) {
      mostrarToast(`Expediente ${r.codigo} creado correctamente.`, 'exito');
      setTimeout(() => window.location.href = 'expediente-detalle.html?codigo=' + r.codigo, 1500);
    } else {
      mostrarToast(r.mensaje || 'Error al crear.', 'error');
      btn.disabled = false;
      btn.textContent = 'Guardar expediente';
    }
  } catch (err) {
    mostrarToast('Error de red al guardar.', 'error');
    btn.disabled = false;
    btn.textContent = 'Guardar expediente';
  }
});
</script>
</body>
</html>

