      <p class="content-lede">Busca un proyecto por su código de expediente. Solo se muestra información pública — nombre, promotor, categoría y estado — sin datos personales, conforme a la Ley 81 de 2019.</p>

      <div class="panel">
        <div class="search-row">
          <input type="text" id="inputCodigo" placeholder="Ej. SP-A8-2026-001">
          <button class="btn btn-brass" id="btnBuscar">Buscar</button>
        </div>
      </div>

      <div class="panel" id="panelResultado" style="display:none;">
        <h3>Resultado</h3>
        <div class="fact-row mt-3">
          <div class="fact"><span class="k">CÓDIGO</span><span class="v"><span class="case-tag" id="rCodigo"></span></span></div>
          <div class="fact"><span class="k">PROYECTO</span><span class="v" id="rProyecto"></span></div>
          <div class="fact"><span class="k">PROMOTOR</span><span class="v" id="rPromotor"></span></div>
          <div class="fact"><span class="k">CONSULTOR RESPONSABLE</span><span class="v" id="rConsultor"></span></div>
          <div class="fact"><span class="k">CATEGORÍA</span><span id="rCategoria"></span></div>
          <div class="fact"><span class="k">ESTADO</span><span id="rEstado"></span></div>
        </div>
        <button type="button" id="btnPdf" class="btn btn-ghost mt-3" style="border:1.5px solid var(--line);">Descargar resumen ejecutivo (PDF)</button>
      </div>

      <div class="panel" id="panelNoEncontrado" style="display:none; border-left:3px solid var(--status-bad);">
        <p style="color:var(--status-bad); font-size:14px;">No se encontró ningún expediente con ese código.</p>
      </div>

      <div class="panel" id="panelSinAcceso" style="display:none; border-left:3px solid var(--status-warn);">
        <p style="color:var(--status-warn); font-size:14px;">Este proyecto no está disponible para consulta pública. El jefe de la consultora puede habilitarlo desde el detalle del expediente.</p>
      </div>
    </div>
  </div>
</div>

<script src="js/lib/jspdf.umd.min.js"></script>
<script src="js/api.js"></script>
<script>
const usuario = requireAuth();
if (usuario) {
  pintarTopbar();

  let expActual = null;

  async function buscar() {
    const codigo = document.getElementById('inputCodigo').value.trim();
    if (!codigo) return;
    document.getElementById('panelResultado').style.display = 'none';
    document.getElementById('panelNoEncontrado').style.display = 'none';
    document.getElementById('panelSinAcceso').style.display = 'none';
    try {
      const r = await fetch('/consulta/' + encodeURIComponent(codigo), { credentials: 'same-origin' });
      // HU-09: sin acceso público el servidor responde 403 y no entrega datos.
      if (r.status === 403) {
        document.getElementById('panelSinAcceso').style.display = 'block';
        return;
      }
      const d = await r.json();
      if (!r.ok || !d.expediente) {
        document.getElementById('panelNoEncontrado').style.display = 'block';
        return;
      }
      expActual = d.expediente;
      document.getElementById('rCodigo').textContent = expActual.codigo;
      document.getElementById('rProyecto').textContent = expActual.proyecto;
      document.getElementById('rPromotor').textContent = expActual.promotor;
      document.getElementById('rConsultor').textContent = expActual.consultor || '—';
      document.getElementById('rCategoria').innerHTML = fichaTier(expActual.categoria);
      document.getElementById('rEstado').innerHTML = `<span class="${claseEstado(expActual.estado)}">${esc(expActual.estado_publico)}</span>`;
      document.getElementById('panelResultado').style.display = 'block';
    } catch (e) {
      document.getElementById('panelNoEncontrado').style.display = 'block';
    }
  }

  document.getElementById('btnBuscar').addEventListener('click', buscar);
  document.getElementById('inputCodigo').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') buscar();
  });

  document.getElementById('btnPdf').addEventListener('click', () => {
    if (!expActual) return;
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();
    doc.setFont("helvetica", "bold"); doc.setFontSize(16);
    doc.text("Resumen Ejecutivo del Expediente", 20, 20);
    doc.setFont("helvetica", "normal"); doc.setFontSize(11);
    const lineas = [
      "Código: " + expActual.codigo,
      "Proyecto: " + expActual.proyecto,
      "Promotor: " + expActual.promotor,
      "Consultor responsable: " + (expActual.consultor || "—"),
      "Categoría: " + expActual.categoria,
      "Estado: " + expActual.estado_publico,
    ];
    let y = 34;
    lineas.forEach(l => { doc.text(l, 20, y); y += 8; });
    doc.save(expActual.codigo + "-resumen.pdf");
  });
}
</script>
</body>
</html>

