 status=200, reason=OK 
 headers={'Server': 'Werkzeug/3.0.4 Python/3.11.18', 'Date': 'Mon, 23 Nov 2026 00:44:03 GMT, Mon, 23 Nov 2026 00:44:03 GMT', 'Content-Disposition': 'inline; filename=estilos.css', 'Content-Type': 'text/css; charset=utf-8', 'Content-Length': '20407', 'Last-Modified': 'Mon, 23 Nov 2026 00:42:17 GMT', 'Cache-Control': 'no-cache', 'ETag': '"1795394537.8912442-20407-2011564415"', 'X-Content-Type-Options': 'nosniff', 'X-Frame-Options': 'DENY', 'Referrer-Policy': 'same-origin', 'Connection': 'close'} 
 body=/* ============================================================
   Permisos Ambientales — Sistema de diseño "Expediente"
   Tinta añil + bronce de sello sobre papel. Sin verde, sin fotos.
   Tipografía: IBM Plex Serif / Plex Sans / Plex Mono
   ============================================================ */

:root {
  --ink: #16213e;
  --ink-soft: #4b5875;
  --ink-faint: #8790a6;
  --paper: #f3efe4;
  --paper-deep: #ece5d3;
  --surface: #ffffff;
  --brass: #b3812f;
  --brass-deep: #8a611f;
  --brass-pale: #f1e4c9;
  --line: #ddd3bc;
  --line-soft: #e8e1cf;

  --status-ok: #2e7d4f;
  --status-ok-bg: #e4efe6;
  --status-warn: #b3812f;
  --status-warn-bg: #f4ead2;
  --status-bad: #a23b2e;
  --status-bad-bg: #f3e1dc;
  --status-info: #3b5b8a;
  --status-info-bg: #e2e8f3;

  --radius: 3px;
  --serif: 'IBM Plex Serif', Georgia, serif;
  --sans: 'IBM Plex Sans', -apple-system, 'Segoe UI', sans-serif;
  --mono: 'IBM Plex Mono', 'Courier New', monospace;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  -webkit-font-smoothing: antialiased;
}
a { color: var(--brass-deep); text-decoration: none; }
a:hover { text-decoration: underline; }
h1, h2, h3 { font-family: var(--serif); font-weight: 600; margin: 0; color: var(--ink); }
p { margin: 0; }
button, input, select, textarea { font-family: inherit; }
:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }

/* ---- textura de fondo: curvas de nivel topográficas, muy tenues ---- */
.topo-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.5;
}

/* ============== SELLO (marca) ============== */
.seal {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.seal svg { width: 26px; height: 26px; }

/* ============================================================
   PANTALLA DE ACCESO (login / registro) — hoja de expediente
   ============================================================ */
.doc-screen {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
}
.doc-sheet {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 560px;
  background: var(--surface);
  border: 1.5px solid var(--ink);
  box-shadow: 6px 6px 0 var(--brass-pale);
}
.doc-letterhead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 22px 28px;
  border-bottom: 1px solid var(--line);
  color: var(--ink);
}
.doc-letterhead .id {
  display: flex;
  align-items: center;
  gap: 12px;
}
.doc-letterhead .id b {
  font-family: var(--serif);
  font-size: 15px;
  font-weight: 600;
  line-height: 1.25;
  display: block;
}
.doc-letterhead .id span {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--ink-soft);
  letter-spacing: 0.02em;
}
.doc-letterhead .ref {
  font-family: var(--mono);
  font-size: 12px;
  color: var(--ink-faint);
  text-align: right;
  line-height: 1.6;
}
.doc-body { padding: 36px 28px 30px; }
.doc-body h1 {
  font-size: clamp(24px, 4vw, 30px);
  line-height: 1.2;
  max-width: 18ch;
  margin-bottom: 10px;
}
.doc-lede {
  color: var(--ink-soft);
  font-size: 14.5px;
  line-height: 1.6;
  max-width: 46ch;
  margin-bottom: 30px;
}

/* ---- campos estilo "formulario en papel": subrayado, no caja ---- */
.doc-field { margin-bottom: 22px; }
.doc-field label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--ink-soft);
  margin-bottom: 7px;
  font-family: var(--mono);
  letter-spacing: 0.02em;
}
.doc-field input,
.doc-field select,
.doc-field textarea {
  width: 100%;
  border: none;
  border-bottom: 1.5px solid var(--line);
  background: transparent;
  padding: 8px 2px 10px;
  font-size: 16px;
  color: var(--ink);
  transition: border-color .15s ease;
}
.doc-field textarea { resize: vertical; min-height: 70px; }
.doc-field input:focus,
.doc-field select:focus,
.doc-field textarea:focus {
  border-bottom-color: var(--brass);
  outline: none;
}
.doc-field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px 24px; }
@media (max-width: 520px) { .doc-field-row { grid-template-columns: 1fr; } }

/* ---- botón sello ---- */
.btn-stamp {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 13px 20px;
  margin-top: 4px;
  border: 1.5px solid var(--ink);
  background: var(--brass);
  color: var(--surface);
  font-family: var(--serif);
  font-size: 15.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background .15s ease, transform .1s ease;
}
.btn-stamp:hover { background: var(--brass-deep); }
.btn-stamp:active { transform: translateY(1px); }
.btn-stamp:disabled { background: var(--ink-faint); border-color: var(--ink-faint); cursor: not-allowed; }

.doc-footnote {
  margin-top: 26px;
  padding-top: 18px;
  border-top: 1px dashed var(--line);
  font-size: 12.5px;
  color: var(--ink-faint);
  line-height: 1.6;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
.doc-footnote a { color: var(--brass-deep); font-weight: 500; }

.doc-msg {
  margin-top: 18px;
  padding: 11px 14px;
  border: 1px solid transparent;
  font-size: 14px;
  line-height: 1.5;
  display: none;
}
.doc-msg.show { display: block; }
.doc-msg.ok { background: var(--status-ok-bg); color: var(--status-ok); border-color: #c3dccb; }
.doc-msg.error { background: var(--status-bad-bg); color: var(--status-bad); border-color: #e4c3ba; }

/* ============================================================
   APP SHELL — riel oscuro + contenido sobre papel
   ============================================================ */
/* minmax(0, 1fr): la columna principal puede achicarse, asi las tablas anchas
   se desplazan dentro de su panel en vez de empujar toda la pagina. */
.shell { display: grid; grid-template-columns: 224px minmax(0, 1fr); min-height: 100vh; }
@media (max-width: 820px) { .shell { grid-template-columns: minmax(0, 1fr); } .rail { display: none; } }

.rail {
  background: var(--ink);
  color: #dfe4ef;
  padding: 24px 0;
  display: flex;
  flex-direction: column;
}
.rail-brand {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 0 22px 22px;
  margin-bottom: 8px;
  border-bottom: 1px solid rgba(255,255,255,0.12);
}
.rail-brand .seal { color: #dfe4ef; width: 34px; height: 34px; }
.rail-brand .seal svg { width: 20px; height: 20px; }
.rail-brand b {
  font-family: var(--serif);
  font-size: 14.5px;
  line-height: 1.25;
  display: block;
  color: #fff;
}
.rail-brand span {
  font-family: var(--mono);
  font-size: 10.5px;
  color: #9aa5c0;
}
.rail nav { display: flex; flex-direction: column; margin-top: 6px; }
.rail nav a {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 22px;
  color: #b6bedb;
  font-size: 13.5px;
  font-weight: 500;
  border-left: 3px solid transparent;
}
.rail nav a:hover { color: #fff; text-decoration: none; background: rgba(255,255,255,0.04); }
.rail nav a.active {
  color: #fff;
  border-left-color: var(--brass);
  background: rgba(179,129,47,0.14);
}
.rail nav a svg { width: 17px; height: 17px; flex-shrink: 0; opacity: .85; }
.rail-foot {
  margin-top: auto;
  padding: 16px 22px 0;
  font-size: 11px;
  font-family: var(--mono);
  color: #6f7a9a;
  border-top: 1px solid rgba(255,255,255,0.1);
}

.main { display: flex; flex-direction: column; min-height: 100vh; }
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 32px;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}
.topbar .crumb {
  font-family: var(--mono);
  font-size: 12px;
  color: var(--ink-faint);
}
.topbar .who {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13.5px;
  color: var(--ink-soft);
}
.who .tag {
  font-family: var(--mono);
  font-size: 10.5px;
  padding: 3px 8px;
  background: var(--brass-pale);
  color: var(--brass-deep);
  border-radius: 2px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.who a { color: var(--ink-soft); border-left: 1px solid var(--line); padding-left: 10px; margin-left: 2px; }

.content { padding: 32px 32px 60px; max-width: 1080px; }
.content-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}
.content-head h2 { font-size: 24px; }
.content-head .back { font-family: var(--mono); font-size: 12.5px; color: var(--ink-soft); display: block; margin-bottom: 10px; }
.content-lede { color: var(--ink-soft); font-size: 14px; margin: -14px 0 24px; max-width: 62ch; line-height: 1.6; }

/* ============== PANEL (reemplazo de "card") ============== */
.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-top: 3px solid var(--ink);
  padding: 22px 24px;
  margin-bottom: 20px;
}
.panel h3 {
  font-size: 15.5px;
  margin-bottom: 4px;
}
.panel .panel-note { color: var(--ink-soft); font-size: 13px; margin-bottom: 16px; line-height: 1.6; }

/* ============== MÉTRICAS ============== */
.stat-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; margin-bottom: 24px; }
.stat {
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 3px solid var(--brass);
  padding: 18px 20px;
}
.stat .num { font-family: var(--serif); font-size: 32px; font-weight: 600; color: var(--ink); line-height: 1; margin-bottom: 6px; }
.stat .lbl { font-size: 12.5px; color: var(--ink-soft); line-height: 1.4; }

/* ============== LISTAS TIPO REGISTRO ============== */
.reg-list { list-style: none; margin: 0; padding: 0; }
.reg-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 0;
  border-bottom: 1px solid var(--line-soft);
  font-size: 13.5px;
}
