    <div class="content">
      <div class="content-head">
        <h2>Equipo de consultores</h2>
      </div>
      <p class="content-lede">Da de alta a los consultores de tu consultora, desactiva a quien ya no trabaja contigo y pasa sus expedientes a otro consultor. Un consultor desactivado no puede iniciar sesión, pero sus expedientes y su historial se conservan.</p>

      <div id="aviso-equipo" class="panel" style="display:none; margin-bottom:18px;"></div>

      <div class="panel" style="margin-bottom:22px;">
        <h3>Dar de alta un consultor</h3>
        <form id="form-alta" class="form-alta" novalidate>
          <div class="campo">
            <label for="alta-nombre">Nombre completo</label>
            <input type="text" id="alta-nombre" maxlength="255" autocomplete="off" required>
          </div>
          <div class="campo">
            <label for="alta-email">Correo</label>
            <input type="email" id="alta-email" maxlength="255" autocomplete="off" required>
          </div>
          <p class="panel-note" style="grid-column:1 / -1; margin:0;">El sistema genera una contraseña temporal que verás una sola vez. El consultor debe cambiarla en «Mi cuenta» en su primer ingreso.</p>
          <details style="grid-column:1 / -1;">
            <summary style="cursor:pointer; font-size:13.5px;">Prefiero definir yo la contraseña</summary>
            <div class="form-alta" style="margin-top:10px;">
              <div class="campo">
                <label for="alta-password">Contraseña</label>
                <input type="password" id="alta-password" maxlength="128" autocomplete="new-password">
              </div>
              <div class="campo">
                <label for="alta-password2">Repetir contraseña</label>
                <input type="password" id="alta-password2" maxlength="128" autocomplete="new-password">
              </div>
              <p class="panel-note" style="grid-column:1 / -1; margin:0;">Mínimo 8 caracteres, con al menos un número y una letra mayúscula (política del Sprint 6). Igual deberá cambiarla al entrar.</p>
            </div>
          </details>
          <div style="grid-column:1 / -1;">
            <button type="submit" class="btn btn-brass" id="btn-alta">Dar de alta</button>
          </div>
        </form>
      </div>

      <div class="panel" style="padding:0; overflow-x:auto;">
        <table class="ledger tarjetas" style="margin:0; width:100%; table-layout:auto;">
          <thead>
            <tr>
              <th style="padding-left:24px;">Nombre</th>
              <th>Correo</th>
              <th style="white-space:nowrap;">Estado</th>
              <th style="white-space:nowrap;">Expedientes</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody id="tabla-equipo"></tbody>
        </table>
      </div>
    </div>
  </div>
</div>

<style>
  .form-alta { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px 18px; margin-top: 14px; }
  .form-alta .campo { display: flex; flex-direction: column; gap: 6px; }
  .form-alta label { font-family: var(--mono); font-size: 11px; color: var(--ink-soft); text-transform: uppercase; letter-spacing: 0.03em; }
  .form-alta input, .acciones select {
    padding: 9px 10px; border: 1px solid var(--line); border-radius: 4px; font: inherit; font-size: 14px; background: var(--surface); min-width: 0;
  }
  .acciones { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; justify-content: flex-end; }
  .acciones .btn { padding: 6px 12px; font-size: 13px; }
  #aviso-equipo.ok { border-left: 4px solid var(--status-ok, #2e7d4f); }
  #aviso-equipo.error { border-left: 4px solid var(--status-bad, #a23b2e); }
  @media (max-width: 640px) {
    .form-alta { grid-template-columns: minmax(0, 1fr); }
    .acciones { justify-content: flex-end; }
  }
</style>

<script src="js/api.js"></script>
<script>
// HU-16 (equipo de consultores): solo el jefe. El servidor responde 403 a cualquier otro rol.
let consultores = [];

function aviso(texto, ok, extra) {
  const el = document.getElementById('aviso-equipo');
  el.className = 'panel ' + (ok ? 'ok' : 'error');
  el.replaceChildren(document.createTextNode(texto));
  if (extra) el.append(extra);
  el.style.display = 'block';
  el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function datosDeAcceso(email, temporal) {
  // Igual que la cuenta del promotor: la contraseña temporal se muestra una sola vez.
  const caja = document.createElement('div');
  caja.style.marginTop = '8px';
  const titulo = document.createElement('div');
  titulo.textContent = 'Entrégale estos datos por un canal seguro; se muestran una sola vez:';
  const datos = document.createElement('div');
  datos.id = 'datos-acceso';
  datos.style.cssText = 'margin-top:6px; font-family:var(--mono); word-break:break-all;';
  datos.textContent = `${email} · ${temporal}`;
  caja.append(titulo, datos);
  return caja;
}

function problemaDePassword(p) {
  // Misma politica que el servidor (Sprint 6).
  if (p.length < 8) return 'La contraseña debe tener al menos 8 caracteres.';
  if (!/[0-9]/.test(p)) return 'La contraseña debe incluir al menos un número.';
  if (!/[A-ZÁÉÍÓÚÑ]/.test(p)) return 'La contraseña debe incluir al menos una letra mayúscula.';
  return null;
}

function accionesDe(c) {
  if (c.activo) {
    return `<button type="button" class="btn btn-ghost" style="border:1.5px solid var(--line);"
              data-desactivar="${c.id}">Desactivar</button>`;
  }
  const destinos = consultores.filter(d => d.activo && d.id !== c.id);
  let reasignar = '';
  if (c.expedientes > 0 && destinos.length) {
    reasignar = `
      <select data-destino-de="${c.id}" aria-label="Consultor que recibe los expedientes">
        ${destinos.map(d => `<option value="${d.id}">${esc(d.nombre)}</option>`).join('')}
      </select>
      <button type="button" class="btn btn-brass" data-reasignar="${c.id}">Reasignar</button>`;
  } else if (c.expedientes > 0) {
    reasignar = '<span class="panel-note" style="margin:0;">No hay otro consultor activo para recibir sus expedientes.</span>';
  }
  return `${reasignar}
    <button type="button" class="btn btn-ghost" style="border:1.5px solid var(--line);"
            data-activar="${c.id}">Reactivar</button>`;
}

function render() {
  const tbody = document.getElementById('tabla-equipo');
  if (!consultores.length) {
    tbody.innerHTML = '<tr><td colspan="5" class="sin-etiqueta" data-label="" style="padding:24px; color:var(--ink-faint); text-align:center;">Todavía no hay consultores.</td></tr>';
    return;
  }
  tbody.innerHTML = consultores.map(c => `
    <tr>
      <td data-label="Nombre" style="padding-left:24px;">${esc(c.nombre)}</td>
      <td data-label="Correo">${esc(c.email)}</td>
      <td data-label="Estado" style="white-space:nowrap;">
        <span class="${c.activo ? 'status status-ok' : 'status status-bad'}">${c.activo ? 'Activo'... (set the log level to DEBUG or TRACE to see the full content)

GET Response : url=http://localhost:5000/consultores 
 status=403, reason=FORBIDDEN 
 headers={'Server': 'Werkzeug/3.0.4 Python/3.11.18', 'Date': 'Mon, 23 Nov 2026 00:44:03 GMT', 'Content-Type': 'application/json', 'Content-Length': '151', 'X-Content-Type-Options': 'nosniff', 'X-Frame-Options': 'DENY', 'Referrer-Policy': 'same-origin', 'Cache-Control': 'no-store', 'Vary': 'Cookie', 'Connection': 'close'} 
 body={"error":"Solo el jefe de la consultora gestiona a los consultores.","mensaje":"Solo el jefe de la consultora gestiona a los consultores.","ok":false}
